/**
 * Escapes SQLite LIKE wildcards so the query matches literally: `%`, `_` and
 * the escape character itself (`\`) are ordinary characters to the caller
 * (ADR 0007 rule 1), so they must stop meaning anything to LIKE here.
 */
function escapeLike(raw: string): string {
  return raw.replace(/[\\%_]/g, (char) => `\\${char}`);
